        let c = riSafe(-3, 3); if(c===0) c=2;
        let d = riSafe(2, 4);
        let e = riSafe(-4, 4); if(e===0) e=-1;
        
        const left = `${a===1?'':a}x^2 ${b>0?'+':''}${b===1?'':(b===-1?'-':b)}x ${c>0?'+':''}${c}`;
