        const sol = `전개식에서 $x^2$ 이 나오는 항은 $(${a===1?'':a}x^2) \\times (${e>0?'+':''}${e})$ 와 $(${b>0?'+':''}${b===1?'':(b===-1?'-':b)}x) \\times (${d===1?'':d}x)$ 이다.\\n계수를 계산하면 $(${a}) \\times (${e}) + (${b}) \\times (${d}) = ${a*e} + ${b*d} = ${ans}$ 이다.`;
        const hints = ["분배법칙을 이용하여 두 항을 곱했을 때 차수가 $x^2$ 이 되는 조합만 찾아서 계산한다."];
        
