        const hints = ["세제곱 전개 공식에서 $x$ 가 1차인 항이 무엇인지 떠올려 계수를 구한다."];
        
        return makeMc(q, dists.map(c => `$${c}$`), 0, `$${ans}$`, `${ans}`, sol, hints, "세제곱 전개식", STD_01_01);
