      "나머지정리에 의해 다항식 $P(x)$를 일차식 $2x-1$로 나눈 나머지는 나누는 식이 $0$이 되는 $x = \\dfrac{1}{2}$을 대입한 값 $P\\left(\\dfrac{1}{2}\\right)$과 같다. 다항식에 대입하면 $P\\left(\\dfrac{1}{2}\\right) = 2\\left(\\dfrac{1}{2}\\right)^2 - \\dfrac{1}{2} + 3 = 2\\left(\\dfrac{1}{4}\\right) - \\dfrac{1}{2} + 3 = \\dfrac{1}{2} - \\dfrac{1}{2} + 3 = 3$이 된다. 따라서 나머지는 $3$이다.",
